#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

vector<ll> calc_zigzag(const vector<int>& a, int z) {
    int n = a.size();
    vector<ll> zigzag(n, 0);
    for (int i = 0; i < n; ++i) {
        int idx = i % z;
        if (idx < (z + 1) / 2) {
            zigzag[i] = (ll)a[i] * (idx + 1);
        } else {
            zigzag[i] = (ll)a[i] * (z - idx);
        }
    }
    for (int i = 1; i < n; ++i) {
        zigzag[i] += zigzag[i - 1];
    }
    return zigzag;
}

