#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;
int n, m;
vector<vector<int>> adj;
vector<int> dist1, distN;
vector<int> parent1, parentN;

void bfs(int start, vector<int> &dist, vector<int> &parent) {
    dist.assign(n + 1, INF);
    parent.assign(n + 1, -1);
    queue<int> q;
    q.push(start);
    dist[start] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj[u]) {
            if (dist[v] == INF) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                q.push(v);
            }
        }
    }
}

bool reconstruct_path(int s, int t, vector<int> &parent, vector<int> &path) {
    path.clear();
    int u = t;
    while (u != s && u != -1) {
        path.push_back(u);
        u = parent[u];
    }
    if (u == -1) return false;
    path.push_back(s);
    reverse(path.begin(), path.end());
    return true;
}

