            dp[(type + 1) % 2][j] = min(dp[(type + 1) % 2][j], dp[type % 2][i] + n - j);
            dp[(type + 1) % 2][j - 1] = min(dp[(type + 1) % 2][j - 1], dp[type % 2][i] + n - (j - 1));
            if(j > 0 && cur[j - 1] > 0) have--;
        }
    }
    for(int i = 0; i <= n; ++i) res = min(res, dp[0][i]);
    cout << res;
}

