void update(int idx, int val) {
    while (idx < a.size()) {
        bit[idx] += val;
        idx += idx & -idx;
    }
}

int query(int idx) {
    int res = 0;
    while (idx > 0) {
        res += bit[idx];
        idx -= idx & -idx;
    }
    return res;
}

ll countInversions() {
    bit.assign(a.size() + 1, 0);
    ll inversions = 0;
    for (int i = 0; i < a.size(); i++) {
        inversions += i - query(a[i]);
        update(a[i], 1);
    }
    return inversions;
}

void processQueries() {
