    }
    priority_queue<pair<int, pair<int, int>>> pq;
    for(int i=1; i<n-1; i++){
        pq.push({-min(a[i-1], a[i+1]), {i, i}});
    }
    vector<bool> removed(n, false);
    long long score = 0;
    while(!pq.empty()){
        auto t = pq.top();
        pq.pop();
