        if(i-1 > j+1 && !removed[i-2]){
            pq.push({-min(a[j+1], a[i-2]), {j+1, i-1}});
        }
    }
    if(n > 2){
        score += min(a[0], a[1]);
        score += min(a[n-2], a[n-1]);
    }
    else{
