#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, c;
    cin >> n >> c;
    vector<int> a(n);
    for(auto &x: a) cin >> x;
    vector<vector<int>> dp(n+1, vector<int>(c+1));
    vector<int> fact(n+1, 1);
    vector<int> ifact(n+1, 1);
    for(int i=1;i<=n;i++){
        fact[i] = 1LL * fact[i-1] * i % MOD;
        ifact[i] = 1LL * ifact[i-1] * pow(i, MOD-2, MOD) % MOD;
    }
    dp[0][0] = 1;
    for(int i=0;i<n;i++){
        for(int j=0;j<=c;j++){
            dp[i+1][j] = dp[i][j];
        }
        for(int j=1;j<=c;j++){
            dp[i+1][j] = (dp[i+1][j] + 1LL * dp[i][j-1] * (a[i] == j)) % MOD;
        }
    }
    vector<int> sum(c+1, 0);
    for(int j=0;j<=c;j++){
        for(int i=1;i<=n;i++){
            sum[j] = (sum[j] + dp[i][j]) % MOD;
        }
    }
    vector<int> ans(n+1, 0);
    for(int p=0;p<=n;p++){
        for(int j=0;j<=c;j++){
            if(sum[j] == 0) continue;
            int cnt = 0;
            for(int k=1;k<=p;k++){
                cnt = (cnt + 1LL * fact[p] * ifact[k] % MOD * ifact[p-k] % MOD) % MOD;
            }
            ans[p] = (ans[p] + 1LL * cnt * sum[j] % MOD * pow(c-j, n-p, MOD) % MOD) % MOD;
        }
    }
    for(int i=0;i<n;i++){
        ans[n] = (ans[n] + 1LL * fact[n] * ifact[i] % MOD * ifact[n-i] % MOD) % MOD;
    }
    for(int i=0;i<=n;i++){
        cout << ans[i] << " \n"[i==n];
    }
}

#include <bits/stdc++.h>
using namespace std;

struct BIT {
    vector<int> tree;
    int n;

    BIT(int n) : n(n), tree(n + 1) {}

    void update(int idx) {
        for (++idx; idx <= n; idx += idx & -idx) {
            tree[idx] ^= 1;
        }
    }

    bool query(int idx) {
        bool ans = 0;
        for (++idx; idx > 0; idx -= idx & -idx) {
            ans ^= tree[idx];
        }
        return ans;
    }
};

struct BIT_MAX {
    vector<int> tree;
    int n;

    BIT_MAX(int n) : n(n), tree(n + 1, 0) {}

    void update(int idx, int val) {
        for (++idx; idx <= n; idx += idx & -idx) {
            tree[idx] = max(tree[idx], val);
        }
    }

    int query(int idx) {
        int ans = 0;
        for (++idx; idx > 0; idx -= idx & -idx) {
            ans = max(ans, tree[idx]);
        }
        return ans;
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    vector<int> b(m);
    for(auto &x: a) cin >> x;
    for(auto &x: b) cin >> x;
    vector<pair<int,int>> dishes(n);
    vector<pair<int,int>> pupils(m);
    for(int i = 0; i < n; i++) dishes[i] = {a[i], i};
    for(int i = 0; i < m; i++) pupils[i] = {b[i], i};
    sort(dishes.rbegin(), dishes.rend());
    sort(pupils.rbegin(), pupils.rend());
    BIT bit(n + 1);
    BIT_MAX bit_max(n + 1);
    int dish_idx = 0, pupil_idx = 0;
    int last_cost = -1;
    while(dish_idx < n && pupil_idx < m){
        while(dish_idx < n && bit.query(dish_idx + 1)){
            dish_idx++;
        }
        if(dish_idx == n) break;
        int cost = dishes[dish_idx].first;
        while(pupil_idx < m && pupils[pupil_idx].first >= cost){
            if(!bit.query(dishes[pupils[pupil_idx].second].second + 1)){
                bit.update(dishes[pupils[pupil_idx].second].second + 1);
                bit_max.update(dishes[pupils[pupil_idx].second].second + 1, dishes[pupils[pupil_idx].second].first);
            }
            pupil_idx++;
        }
        bit.update(dish_idx + 1);
        last_cost = bit_max.query(n);
        dish_idx++;
    }
    int q;
    cin >> q;
    while(q--){
        int type, idx, val;
        cin >> type >> idx >> val;
        idx--;
        if(type == 1){
            if(!bit.query(idx + 1)){
                if(last_cost == -1 || val > last_cost){
                    last_cost = val;
                }
            }else{
                bit.update(idx + 1);
                bit_max.update(idx + 1, 0);
                a[idx] = val;
                dishes[idx] = {a[idx], idx};
                sort(dishes.rbegin(), dishes.rend());
                int new_dish_idx = 0;
                while(new_dish_idx < n && new_dish_idx != idx){
                    if(new_dish_idx == dish_idx){
                        if(!bit.query(idx + 1)) break;
                        new_dish_idx++;
                    }
                    if(new_dish_idx == n) break;
                    int cost = dishes[new_dish_idx].first;
                    while(pupil_idx < m && pupils[pupil_idx].first >= cost){
                        if(!bit.query(dishes[pupils[pupil_idx].second].second + 1)){
                            bit.update(dishes[pupils[pupil_idx].second].second + 1);
                            bit_max.update(dishes[pupils[pupil_idx].second].second + 1, dishes[pupils[pupil_idx].second].first);
                        }
                        pupil_idx++;
                    }
                    bit.update(new_dish_idx + 1);
                    last_cost = bit_max.query(n);
                    new_dish_idx++;
                }
            }
            a[idx] = val;
        }else{
            b[idx] = val;
            pupils[idx] = {b[idx], idx};
            sort(pupils.rbegin(), pupils.rend());
            pupil_idx = 0;
            dish_idx = 0;
            bit = BIT(n + 1);
            bit_max = BIT_MAX(n + 1);
            last_cost = -1;
            while(dish_idx < n && pupil_idx < m){
                while(dish_idx < n && bit.query(dish_idx + 1)){
                    dish_idx++;
                }
                if(dish_idx == n) break;
                int cost = dishes[dish_idx].first;
                while(pupil_idx < m && pupils[pupil_idx].first >= cost){
                    if(!bit.query(dishes[pupils[pupil_idx].second].second + 1)){
                        bit.update(dishes[pupils[pupil_idx].second].second + 1);
                        bit_max.update(dishes[pupils[pupil_idx].second].second + 1, dishes[pupils[pupil_idx].second].first);
                    }
                    pupil_idx++;
                }
                bit.update(dish_idx + 1);
                last_cost = bit_max.query(n);
                dish_idx++;
            }
        }
        cout << last_cost << '\n';
    }
}

#include <bits/stdc++.h>
using namespace std;

void solve() {
    int n, m;
    cin >> n >> m;
    int v = 3 * n;
    vector<vector<int>> adj(v + 1);
    vector<int> edges;
    for(int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
        edges.push_back(u);
        edges.push_back(v);
    }

    vector<int> match(v + 1, -1);
    vector<bool> visited(v + 1, false);

    function<bool(int)> augment = [&](int u) -> bool {
        if(visited[u]) return false;
        visited[u] = true;
        for(int v : adj[u]) {
            if(match[v] == -1 || augment(match[v])) {
                match[v] = u;
                match[u] = v;
                return true;
            }
        }
        return false;
    };

    int matching_size = 0;
    for(int i = 1; i <= v; i++) {
        if(match[i] == -1) {
            fill(visited.begin(), visited.end(), false);
            if(augment(i)) {
                matching_size++;
            }
        }
    }

    if(matching_size == n) {
        cout << "Matching\n";
        vector<int> ans;
        for(int i = 0; i < m; i++) {
            int u = edges[2 * i], v = edges[2 * i + 1];
            if(match[u] == v) {
                ans.push_back(i + 1);
            }
        }
        for(int x : ans) cout << x << " ";
        cout << "\n";
        return;
    }

    vector<int> indSet;
    for(int i = 1; i <= v; i++) {
        if(!visited[i]) {
            indSet.push_back(i);
            if(indSet.size() == n) break;
            queue<int> q;
            q.push(i);
            while(!q.empty()) {
                int u = q.front();
                q.pop();
                for(int v : adj[u]) {
                    if(!visited[v]) {
                        visited[v] = true;
                        q.push(v);
                    }
                }
            }
        }
    }

    if(indSet.size() == n) {
        cout << "IndSet\n";
        for(int x : indSet) cout << x << " ";
        cout << "\n";
        return;
    }

    cout << "Impossible\n";
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    int T;
    cin >> T;
    while(T--) {
        solve();
    }
}

