#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> adj;
vector<int> parents, subordinates, limits, affected;
int n, m, dis_cnt = 0;

void preprocess(int cur, int parent) {
    parents[cur] = parent;
    for(int nxt : adj[cur]) {
        preprocess(nxt, cur);
        subordinates[cur] += subordinates[nxt] + 1;
    }
    affected[cur] = subordinates[cur] > limits[cur];
    dis_cnt += affected[cur];
}

void update(int cur) {
    if(affected[cur]) {
        dis_cnt--;
        affected[cur] = false;
    }
    int new_val = subordinates[cur] - (limits[cur] + 1);
    if(new_val > 0) {
        dis_cnt++;
        affected[cur] = true;
    }
    if(cur == 1) return;
    update(parents[cur]);
}

