        int p;
        cin >> p;
        adj[p].push_back(i);
    }

    for(int i=1; i<=n; i++) cin >> limits[i];
    preprocess(1, 1);

    vector<int> ans(m);
    for(int i=0; i<m; i++){
        int q;
        cin >> q;
        q = abs(q);
        update(q);
        ans[i] = dis_cnt;
    }

    for(int a : ans) cout << a << " ";
    cout << "\n";
    return 0;
}

