    for(int i=0; i<n-1; ++i){
        int a, b;
        cin >> a >> b;
        --a, --b;
        edges.push_back({max(a,b), {a,b}});
    }
    sort(edges.begin(), edges.end(), greater<>());
    DSU dsu(n);
    priority_queue<int, vector<int>, greater<>> pq;
    ll total = 0;
    for(auto &[w, e] : edges){
        auto [u, v] = e;
        if(dsu.find(u) != dsu.find(v)){
            dsu.unite(u, v);
            pq.push(w);
            total += (1LL << w);
        }
    }
    while(k--){
        total -= (1LL << pq.top());
        pq.pop();
    }
    vector<int> ans;
    while(!pq.empty()){
        ans.push_back(pq.top()+1);
        pq.pop();
    }
    sort(ans.begin(), ans.end());
    for(auto &x : ans) cout << x << ' ';
}

