    }

    ll zeroCount = count(sardines.begin(), sardines.end(), make_pair(0LL, 0LL));
    ll ans = 1;
    for(const auto& [_, count] : ratioCount){
        ans = (ans * (1 + (1LL << count))) % MOD;
    }
    ans = (ans + zeroCount) % MOD;

    cout << ans;
}

