        ans = (ans + (x[i+1] - x[i]) * (ll(i + 1)) * (ll(N - i - 1)) % MOD) % MOD;
    }
    ans = (ans * mod_exp(mod_exp(2, MOD-2), N-1)) % MOD;
    cout << ans;
}

