            if (dp[i] == 0.0) continue;
            for (int j = 0; j < X; ++j) {
                int next = i + roulette[j];
                if (next >= Y) {
                    dp[Y] += dp[i] / X;
                } else {
                    int E = events[next][0];
                    int A = events[next][1];
