const int MAXN = 300005;
const int MAXB = 20;

int n, q;
int a[MAXN];
vector<int> idx[MAXB];
int bit[MAXN][MAXB];

inline void update(int idx, int bit, int val) {
    for (; idx < MAXN; idx += idx & -idx) {
        bit[idx] = max(bit[idx], val);
    }
}

inline int query(int idx, int bit) {
    int res = 0;
    for (; idx > 0; idx -= idx & -idx) {
        res = max(res, bit[idx]);
    }
    return res;
}

int main(){
