            if(a[i] & (1<<b)){
                idx[b].push_back(i);
            }
        }
        for(int i=0;i<idx[b].size();i++){
            int pos = idx[b][i];
            update(pos, bit[b], pos);
        }
    }
    while(q--){
        int x, y;
        cin >> x >> y;
        bool reachable = false;
        for(int b=0;b<MAXB;b++){
            if((a[x] & (1<<b)) && (a[y] & (1<<b))){
                int res = query(y-1, bit[b]);
                if(res >= x){
                    reachable = true;
                    break;
                }
            }
        }
