        cin >> u >> v;
        adj[u].push_back({v, 1});
        adj[v].push_back({u, 1});
    }
    for(int i=1;i<=k;i++){
        fill(dist.begin(), dist.end(), INF);
        dijkstra(sources[i-1]);
        paths[i] = {1};
    }
    int ans = INF;
    do {
        int currentDiscontent = calculateDiscontent();
        ans = min(ans, currentDiscontent);
    } while (next_permutation(sources.begin(), sources.end()));
    cout << ans;
    return 0;
}

