void dfs(int v, int p) {
    parent[v] = p;
    depth[v] = depth[p] + 1;
    for (int u : adj[v]) {
        if (u != p) {
            dfs(u, v);
            cnt[v] += cnt[u];
        }
    }
    cnt[v]++;
}

void hld(int v, int h) {
    order[v] = h;
    int heavy = -1;
    for (int u : adj[v]) {
        if (u != parent[v] && (heavy == -1 || cnt[u] > cnt[heavy])) {
            heavy = u;
        }
    }
    if (heavy != -1) {
        hld(heavy, h);
    }
    for (int u : adj[v]) {
        if (u != parent[v] && u != heavy) {
            hld(u, u);
        }
    }
}

int lca(int u, int v) {
    while (order[u] != order[v]) {
        if (depth[order[u]] > depth[order[v]]) {
            u = parent[order[u]];
        } else {
            v = parent[order[v]];
        }
    }
    return depth[u] < depth[v] ? u : v;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n;
    adj.resize(n+1);
    depth.resize(n+1, 0);
    cnt.resize(n+1, 0);
    parent.resize(n+1, 0);
    order.resize(n+1, 0);
    for(int i=0; i<n-1; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
