vector<int> median_smoothing(const vector<int>& a) {
    int n = a.size();
    vector<int> b(n);
    b[0] = a[0];
    b[n-1] = a[n-1];
    for (int i = 1; i < n - 1; ++i) {
        int x = a[i-1], y = a[i], z = a[i+1];
        vector<int> med = {x, y, z};
        sort(med.begin(), med.end());
        b[i] = med[1];
    }
    return b;
}

