void dfs_size(int v, int p) {
    sz[v] = 1;
    for (int u : adj[v]) {
        if (u != p) {
            dfs_size(u, v);
            sz[v] += sz[u];
        }
    }
}

void dfs_centroid(int v, int p) {
    int biggest_child = -1;
    for (int u : adj[v]) {
        if (u != p) {
            if (biggest_child == -1 || sz[u] > sz[biggest_child]) {
                biggest_child = u;
            }
        }
    }
    if (biggest_child != -1 && sz[biggest_child] > half_n) {
        dfs_centroid(biggest_child, v);
    } else {
        sub_centroid = v;
        sub_centroid_size = sz[v];
    }
