void multiply(ld A[N][N], ld B[N][N]) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            tmp[i][j] = 0;
            for (int k = 0; k < n; k++) {
                tmp[i][j] += A[i][k] * B[k][j];
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            A[i][j] = tmp[i][j];
        }
    }
}

void power(ld A[N][N], int p) {
    ld res[N][N];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            res[i][j] = (i == j);
        }
    }
    while (p > 0) {
        if (p & 1) multiply(res, A);
        multiply(A, A);
        p >>= 1;
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            A[i][j] = res[i][j];
        }
    }
}

