vector<vector<int>> adj;
vector<int> X, sum_black, sum_white;

bool dfs(int v, int parent_color) {
    int black = 0, white = 0;
    for (int u : adj[v]) {
        if (!dfs(u, parent_color ^ 1)) return false;
        black += sum_black[u];
        white += sum_white[u];
    }
    if (parent_color == 0) {
        if (black > X[v]) return false;
        sum_black[v] = X[v];
        sum_white[v] = white;
    } else {
        if (white > X[v]) return false;
        sum_black[v] = black;
        sum_white[v] = X[v];
    }
    return true;
}

