                    dp[i][j+1][mask] = max(dp[i][j+1][mask], dp[i][j][mask] + a[i][j+1]);
                }
            }
        }
    }
    long long ans = 0;
    for(int mask=0;mask<(1<<H);mask++){
        ans = max(ans, dp[H-1][W-1][mask]);
    }
