const int MOD = 1e9 + 7;

struct Node {
    int cnt;
    Node* child[26];
    Node() : cnt(0) {
        memset(child, 0, sizeof(child));
    }
};

void insert(Node* root, const string& s) {
    Node* curr = root;
    for (char c : s) {
        if (!curr->child[c - 'a']) {
            curr->child[c - 'a'] = new Node();
        }
        curr = curr->child[c - 'a'];
    }
    curr->cnt++;
}

long long dp[100005];

int main() {
