    cin >> t;
    int n = t.size();
    dp[0] = 1;
    for (int i = 1; i <= n; ++i) {
        dp[i] = 0;
        Node* curr = root;
        for (int j = i; j > 0; --j) {
            char c = t[j - 1];
            if (!curr->child[c - 'a']) break;
            curr = curr->child[c - 'a'];
            if (curr->cnt > 0) {
                dp[i] = (dp[i] + dp[j - 1]) % MOD;
            }
        }
    }
    cout << dp[n] << "\n";
}

