    for (int i = 0; i < n; ++i) {
        if (jars[i] >= k) {
            maxHeap.push({jars[i], i});
        }
    }

    int pigletHoney = 0;
    while (!maxHeap.empty()) {
        auto [amount, index] = maxHeap.top();
