            maxHeap.push({amount, index});
        }
    }

    for (int& a : jars) {
        if (!maxHeap.empty() && maxHeap.top().second == index) {
            maxHeap.pop();
        }
        if (a < k) {
            pigletHoney += a;
        }
    }

    cout << pigletHoney;
