bool found_cycle = false;
vector<int> cycle;

void dfs(int u, int prev, int k) {
    if (found_cycle) return;
    visited[u] = true;
    parent[u] = prev;

    for (int v : adj[u]) {
        if (v == prev) continue;
        if (!visited[v]) {
            dfs(v, u, k);
        } else {
            found_cycle = true;
            int cur = u;
            cycle.push_back(cur);
            while (cur != v) {
                cur = parent[cur];
                cycle.push_back(cur);
            }
            cycle.push_back(u);
            break;
        }
    }
}

