bool vis[MXN][MXN][MXN];

void dfs(int x, int y, int z) {
    if (vis[x][y][z]) return;
    vis[x][y][z] = true;
    for (int i = 0; i < 3; ++i) {
        int nx = x + dx[i], ny = y + dy[i], nz = z + dz[i];
        if (nx >= 1 && nx <= n && ny >= 1 && ny <= m && nz >= 1 && nz <= k && grid[nx][ny][nz] == '1')
            dfs(nx, ny, nz);
    }
}

int count_neighbors(int x, int y, int z) {
    int cnt = 0;
    for (int i = 0; i < 3; ++i) {
        int nx = x + dx[i], ny = y + dy[i], nz = z + dz[i];
        if (nx >= 1 && nx <= n && ny >= 1 && ny <= m && nz >= 1 && nz <= k && grid[nx][ny][nz] == '1')
            cnt++;
    }
    return cnt;
}

